const SERVICE_UNAVAILABLE_MAX_MS = 8_000;

function serviceUnavailableDelayMs(attempt: number): number {
  const delay = SERVICE_UNAVAILABLE_BASE_MS * 2 ** (attempt - 1);
  return Math.min(delay, SERVICE_UNAVAILABLE_MAX_MS);
}
